import AppKit

/// The Clip tab's **Transition** section (spec §4.3) — the one group that is
/// not about the layer's own pixels but about how it MEETS the clip before
/// it. `ClipPane` shows it only for a single clip with an overlap
/// (`ClipPane.makeSections()`), which is the only state in which an overlap
/// has a transition to describe.
///
/// An `extension VideoPane` in a file of its own because `VideoPane.swift`
/// stood at 1465 lines against the ~400-line rule for new files and the
/// section is about to grow the Curve popup and the Crossfade Audio check
/// row road map 5's E1 adds. The move cost no visibility: `binding` is
/// internal and the row builders are free functions.
extension VideoPane {
    // MARK: Transition

    /// The section's five rows: which transition, how it is eased, whether
    /// it crossfades the sound and in which shape (format 29, spec §11
    /// AU-115; enabled while Crossfade Audio is on), and how long the
    /// overlap is.
    ///
    /// **The Curve and Crossfade Audio rows READ the snapshot's lenient
    /// defaults** — `linear` and `false` — which is what a clip with no
    /// stored transition draws, and what a version-6 file's transition
    /// means. They deliberately do not show what the core would MINT: the
    /// section has to say what is there.
    ///
    /// **And when `transitionIn` is nil, each of the three sends every key.**
    /// The Kind popup's index 0 is None, so a clip under an overlap is one
    /// click away from having no stored transition at all while still being
    /// drawn as a cross dissolve; a one-key `set_transition_style` on that
    /// clip would mint `ease_in_out`/`true` underneath and the untouched
    /// row would silently change its value. Sending both makes the minted
    /// transition exactly what the section was showing, with only the
    /// touched value moved. With a transition stored, each row sends its one
    /// key and the core keeps the other. `TextPane`'s animation section is
    /// the precedent, applied to two scalars rather than to one object.
    func transitionSection(_ clip: UInt32) -> InspectorSection {
        let binding = self.binding
        let kinds = TransitionKind.allCases
        let items = ["None"] + kinds.map { $0.displayName }
        let curves = Curve.allCases
        /// The overlap read fresh: changing the duration MOVES the clip
        /// (§6 `set_transition_duration`), so the captured start would be
        /// wrong one edit later.
        func overlapSeconds() -> Double {
            guard let current = binding.snapshot.clip(clip) else { return 0 }
            let earlier = binding.snapshot.clips(onTrack: current.track)
                .filter { $0.start < current.start }
            guard let previous = earlier.last else { return 0 }
            return ReelTime.seconds(max(previous.end - current.start, 0))
        }
        func stored() -> TransitionSnapshot? { binding.snapshot.clip(clip)?.transitionIn }
        func curve() -> Curve { stored()?.curve ?? .linear }
        func crossfades() -> Bool { stored()?.audio ?? false }
        let shapes = FadeShape.allCases
        func shape() -> FadeShape { stored()?.audioShape ?? .plus3Db }
        /// The style write, carrying the other rows' DISPLAYED values too
        /// whenever there is nothing stored to keep them (see the doc above).
        func styleOps(curve next: Curve?, audio: Bool?, shape nextShape: FadeShape? = nil)
            -> [ReelOp]
        {
            if stored() == nil {
                return [
                    .setTransitionStyle(
                        clip: clip, curve: next ?? curve(), audio: audio ?? crossfades(),
                        audioShape: nextShape ?? shape())
                ]
            }
            return [
                .setTransitionStyle(clip: clip, curve: next, audio: audio, audioShape: nextShape)
            ]
        }
        return InspectorSection(
            id: "video.transition", title: "Transition",
            summary: {
                guard let transition = stored() else { return "none" }
                return transition.kind.displayName.lowercased()
                    + " · " + transition.curve.displayName.lowercased()
                    + String(format: " · %.2f s", overlapSeconds())
            },
            defaultExpanded: false,
            rows: [
                inspectorPopupRow(
                    "Kind", binding, name: "Set Transition", items: items,
                    read: {
                        guard let kind = binding.snapshot.clip(clip)?.transitionIn?.kind else {
                            return 0
                        }
                        return (kinds.firstIndex(of: kind) ?? 0) + 1
                    },
                    ops: { index in
                        let kind = index == 0 ? nil : kinds[min(max(index - 1, 0), kinds.count - 1)]
                        return [.setTransition(clip: clip, kind: kind)]
                    }, resets: false),
                inspectorPopupRow(
                    "Curve", binding, name: "Transition Curve",
                    items: curves.map { $0.displayName },
                    read: { curves.firstIndex(of: curve()) ?? 0 },
                    ops: { index in
                        styleOps(
                            curve: curves[min(max(index, 0), curves.count - 1)], audio: nil)
                    }, resets: false),
                inspectorCheckRow(
                    "Crossfade Audio", binding, name: "Transition Audio",
                    read: crossfades,
                    ops: { value in styleOps(curve: nil, audio: value) }, resets: false),
                inspectorPopupRow(
                    "Crossfade Shape", binding, name: "Crossfade Shape",
                    items: shapes.map { $0.title },
                    read: { shapes.firstIndex(of: shape()) ?? 0 },
                    ops: { index in
                        styleOps(
                            curve: nil, audio: nil,
                            shape: shapes[min(max(index, 0), shapes.count - 1)])
                    }, enabled: crossfades, resets: false),
                inspectorValueRow(
                    "Duration", binding, name: "Transition Duration", unit: " s", decimals: 2,
                    min: 0.02, max: 10, quick: [0.25, 0.5, 1, 2], slider: false,
                    read: overlapSeconds,
                    ops: { value in
                        [
                            .setTransitionDuration(
                                clip: clip,
                                duration: binding.frameTicks(seconds: value))
                        ]
                    }, resets: false),
            ])
    }
}
import AppKit

/// The two commands the inspector made real — Add Action at the playhead
/// (⌥⌘K) and Clip ▸ Transition ▸ — with the no-footage sheet and its Shift
/// Clips Left, and `transitionPlacement`, which their validator arm in
/// `EditorViewController+Inspector.swift` also reads. A pure move out of that
/// file (road map creator-jobs TX2a's toll).
extension EditorViewController {
    // MARK: - Commands the inspector made real

    /// ⌥⌘K and the action lane's `+`: an action at the playhead on the
    /// selected clip, then selected (spec §11 CI-1). `add_action` takes CLIP
    /// time (§6), and refuses an overlap or a span past the clip end — so the
    /// only check here is that the playhead is actually on a selected clip.
    func addActionAtPlayheadCommand() {
        guard let document = document,
              let clip = selectedClips.first(where: { $0.contains(document.playhead) })
        else {
            NSSound.beep()
            return
        }
        let at = clip.clipTime(document.playhead)
        document.applyEdit("Add Action", .addAction(clip: clip.id, at: at))
        selectAddedAction(on: clip.id, at: at, countBefore: clip.actions.count)
    }

    /// Clip ▸ Transition ▸ — the sender's tag indexes `TransitionKind.allCases`
    /// and −1 is None, the same table the Clip tab's Transition section's popup
    /// offers.
    ///
    /// A kind is sent one of two ways per clip, and the choice is the
    /// clip's own placement: a clip that already OVERLAPS its predecessor
    /// gets `set_transition`, which names the kind and keeps the style; a
    /// clip at a HARD CUT gets `add_transition`, which makes the overlap out
    /// of the two clips' handles first. Anything else — a gap, or the first
    /// clip on a track — is SKIPPED rather than sent, because
    /// `ReelProject.applying` throws on the first `Err` and one clip at a
    /// gap would abort the whole selection.
    ///
    /// **None (tag −1) never reaches `add_transition`.** It is a clear, it
    /// goes to every selected clip whatever its placement, and an absent
    /// kind on `add_transition` would ADD a dissolve rather than remove one.
    func setTransitionKindCommand(_ sender: Any?) {
        guard let document = document, let tag = (sender as? NSMenuItem)?.tag,
              !selectedClips.isEmpty
        else {
            NSSound.beep()
            return
        }
        let kinds = TransitionKind.allCases
        guard tag < 0 || kinds.indices.contains(tag) else {
            NSSound.beep()
            return
        }
        guard tag >= 0 else {
            document.applyEdit(
                "Set Transition", selectedClips.map { .setTransition(clip: $0.id, kind: nil) })
            return
        }
        let kind = kinds[tag]
        let snapshot = document.editedProject.snapshot
        let half = ReelTime.snapToFrame(
            ReelTime.ticks(seconds: 0.5), fps: snapshot.canvas.fps)
        var ops: [ReelOp] = []
        var requested: [UInt32] = []
        for clip in selectedClips {
            switch transitionPlacement(of: clip, in: snapshot) {
            case .overlap:
                ops.append(.setTransition(clip: clip.id, kind: kind))
            case .hardCut:
                ops.append(
                    .addTransition(clip: clip.id, kind: kind, duration: half, align: .center))
                requested.append(clip.id)
            case .neither:
                continue
            }
        }
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        // Every `add_transition` in the batch can come back REFUSED —
        // neither side of the cut had a frame to spare, which is EVERY cut
        // between two clips that each use their whole file, and since
        // deepening D2·3 the core says so in its own sentence. `.project` is
        // nil for that arm as it is for an identity, so the trial below
        // reads the same either way. That has to be
        // SAID (road map 5 §3g): a bare beep is all `applyEdit` gives a
        // batch that changed nothing, and a person placing whole recordings
        // back to back has no way to guess that a transition is built from
        // footage beyond the cut. So TRY the batch first, on the container
        // the edit lands in (`inspectorProbe`'s trial), and ask the clips
        // themselves — a landed `add_transition` leaves its clip overlapping
        // its predecessor. A throw is left to `applyEdit`, which presents
        // the core's own sentence.
        let trial: ProjectSnapshot?
        do {
            trial = try document.editedProject.applying(ops).project?.snapshot
        } catch {
            document.applyEdit("Set Transition", ops)
            return
        }
        let added = requested.contains { id in
            guard let after = trial, let clip = after.clips.first(where: { $0.id == id })
            else { return false }
            return transitionPlacement(of: clip, in: after) == .overlap
        }
        // Applied whenever something changes — a MIXED batch keeps the
        // `set_transition`s that landed — and whenever there was no add to
        // explain, so an all-`set_transition` identity still beeps.
        if trial != nil || requested.isEmpty {
            document.applyEdit("Set Transition", ops)
        }
        if !requested.isEmpty && !added {
            presentNoFootageForTransition(clips: requested, kind: kind, duration: half)
        }
    }

    /// Why Clip ▸ Transition ▸ <kind> did nothing at a hard cut, as a sheet
    /// rather than a beep — and the way to get the transition anyway.
    ///
    /// **Shift Clips Left** re-sends the same cuts as `add_transition` with
    /// `ripple` (spec §11, R5-3's amendment): each incoming clip, and every
    /// clip at or after its cut on an unlocked track, slides left by the
    /// same half second, so the overlap is made of footage the clips already
    /// show and the project gets shorter. It is offered only here, where the
    /// handle form found nothing at all, because a cut with ANY footage to
    /// spare got a shorter transition and never reaches this sheet. The
    /// MCP tool's refusal says the same thing in the op's words
    /// (`AgentServer+Transitions.swift`).
    ///
    /// The sheet's completion is not an AppKit event, so the edit goes
    /// through `performGroupedEdit` (app/CLAUDE.md's undo pitfall), and it is
    /// one undo step whatever the number of cuts.
    private func presentNoFootageForTransition(
        clips: [UInt32], kind: TransitionKind, duration: Ticks
    ) {
        guard let window = view.window else {
            NSSound.beep()
            return
        }
        let one = clips.count == 1
        let alert = NSAlert()
        alert.messageText =
            one
            ? "There’s no extra footage at this cut for a transition."
            : "There’s no extra footage at these cuts for a transition."
        alert.informativeText =
            "A transition overlaps two clips, so it needs footage past the end of the "
            + "first clip or before the start of the second. A clip that uses its whole "
            + "file has none.\n\nShift Clips Left makes the overlap by sliding "
            + (one ? "the second clip" : "the second clip at each cut")
            + " — and everything after it on unlocked tracks — left by half a second. "
            + "The project gets shorter by the same amount."
        alert.addButton(withTitle: "Shift Clips Left")
        alert.addButton(withTitle: "Cancel")
        alert.beginSheetModal(for: window) { [weak self, weak document] response in
            guard response == .alertFirstButtonReturn, let self = self, let document = document
            else { return }
            document.performGroupedEdit(
                "Add Transition", self.shiftingOps(clips, kind: kind, duration: duration))
        }
    }

    /// Shift Clips Left's ops, each decided against the project the EARLIER
    /// ones leave behind rather than against the snapshot the sheet was
    /// built from.
    ///
    /// One ripple slides every clip at or after its cut on every unlocked
    /// track, and a clip whose PREDECESSOR began before that cut does not
    /// slide with it — so a second chosen cut can already be an overlap by
    /// the time its own op runs. `add_transition` answers that with an
    /// `Err` ("not at a hard cut"), `ReelProject.applying` THROWS on an
    /// `Err`, and the throw takes the whole batch with it: the first
    /// shift — which had already made the second cut's overlap — is lost,
    /// and the person is shown a sentence about a clip they did not point
    /// at. Re-deciding sends `set_transition` for a cut that is now an
    /// overlap, which is what Clip ▸ Transition ▸ sends for an overlap
    /// anyway, so every cut chosen ends up carrying the kind.
    ///
    /// An op the running project declines is dropped rather than carried:
    /// what `performGroupedEdit` is handed has already been shown to apply,
    /// one op at a time, to the project it will be replayed against.
    private func shiftingOps(
        _ clips: [UInt32], kind: TransitionKind, duration: Ticks
    ) -> [ReelOp] {
        guard let document = document else { return [] }
        var project = document.editedProject
        var ops: [ReelOp] = []
        for id in clips {
            guard let clip = project.snapshot.clips.first(where: { $0.id == id }) else { continue }
            let op: ReelOp
            switch transitionPlacement(of: clip, in: project.snapshot) {
            case .overlap:
                op = .setTransition(clip: id, kind: kind)
            case .hardCut:
                op = .addTransition(
                    clip: id, kind: kind, duration: duration, align: .center, ripple: true)
            case .neither:
                continue
            }
            guard let next = (try? project.applying(op))?.project else { continue }
            ops.append(op)
            project = next
        }
        return ops
    }

    /// Where a clip sits relative to the clip before it on its track, which
    /// is what decides how Clip ▸ Transition ▸ writes a kind onto it.
    enum TransitionPlacement {
        case overlap
        case hardCut
        case neither
    }

    /// `roll`'s test, in Swift: the predecessor is whatever ends EXACTLY
    /// where this clip begins (`EditorViewController+Edge.swift`), and an
    /// overlap is a predecessor that ends after it.
    func transitionPlacement(of clip: ClipSnapshot) -> TransitionPlacement {
        guard let document = document else { return .neither }
        return transitionPlacement(of: clip, in: document.editedProject.snapshot)
    }

    func transitionPlacement(
        of clip: ClipSnapshot, in snapshot: ProjectSnapshot
    ) -> TransitionPlacement {
        let neighbours = snapshot.clips.filter { $0.track == clip.track && $0.id != clip.id }
        if neighbours.contains(where: { $0.start < clip.start && $0.end > clip.start }) {
            return .overlap
    /// a file chooser and the colour needs nothing at all. Not built from an
    /// enum, so no tags: the ops themselves differ only in an argument, but
    /// the paths to them do not.
    func backgroundMenu() -> NSMenu {
        let menu = NSMenu(title: "Add Background")
        menu.addItem(
            item("Solid Color", #selector(EditorViewController.addSolidColorBackground(_:))))
        menu.addItem(item("Image…", #selector(EditorViewController.addImageBackground(_:))))
        return menu
    }

    /// Built from `TransitionKind.allCases` with the case's index as the tag,
    /// so adding a transition to the model adds it to this menu for free.
    func transitionMenu() -> NSMenu {
        let menu = NSMenu(title: "Transition")
        for (index, kind) in TransitionKind.allCases.enumerated() {
            menu.addItem(
                tagged(kind.displayName, #selector(EditorViewController.setTransitionKind(_:)), index))
        }
        menu.addItem(.separator())
        menu.addItem(
            tagged("None", #selector(EditorViewController.setTransitionKind(_:)), -1))
        return menu
    }

    /// Clip ▸ Motion: one submenu per slot, then Preview.
    func motionMenu() -> NSMenu {
        let menu = NSMenu(title: "Motion")
        let edges = EdgeMotion.allCases.map(\.displayName)
        menu.addItem(
            submenuItem(
                motionSlotMenu("In", edges, #selector(EditorViewController.setMotionIn(_:)))))
        menu.addItem(
            submenuItem(
                motionSlotMenu("Out", edges, #selector(EditorViewController.setMotionOut(_:)))))
        menu.addItem(
            submenuItem(
                motionSlotMenu(
                    "During", DuringMotion.allCases.map(\.displayName),
                    #selector(EditorViewController.setMotionDuring(_:)))))
        menu.addItem(.separator())
    case pushDown = "push_down"
    case wipe
    case slide
    case zoom
    case wipeLeft = "wipe_left"
    case wipeUp = "wipe_up"
    case wipeDown = "wipe_down"

    var displayName: String {
        switch self {
        case .crossDissolve: return "Cross Dissolve"
        case .fadeBlack: return "Fade Through Black"
        case .fadeWhite: return "Fade Through White"
        case .pushLeft: return "Push Left"
        case .pushRight: return "Push Right"
        case .pushUp: return "Push Up"
        case .pushDown: return "Push Down"
        case .wipe: return "Wipe"
        case .slide: return "Slide"
        case .zoom: return "Zoom"
        case .wipeLeft: return "Wipe Left"
        case .wipeUp: return "Wipe Up"
        case .wipeDown: return "Wipe Down"
        }
    }
}

// MARK: - Canvas

/// The document's fixed canvas (spec §5.2 `canvas`).
struct CanvasSnapshot: Codable, Equatable {

//! The `ripple` half of `add_transition` — the overlap made by SHIFTING
//! rather than out of the two clips' handles.
//!
//! Cut out of `edit_transition.rs` under the size rule, a pure move. It
//! sits in its own file rather than beside the handle form because the two
//! answer the same question out of different material: the handle form
//! spends unused source and moves nothing, while this one spends the
//! TIMELINE and moves every clip at or after the cut, which is
//! `close_gap`'s set and `close_gap`'s rules. `add_transition` reads the
//! arguments, finds the cut and hands over here (spec §11, R5-3's
//! amendment of 2026-09-16); nothing else calls it.

use crate::edit_time::{locked_track, shift_clips, shifted, unlocked_tracks};
use crate::edit_transition::transition_too_short;
use crate::model::{Clip, Project, Transition, TransitionKind};
use crate::outcome::Outcome;
use crate::time::{frames_back, frames_in, frames_within, snap_up_to_frame, Ticks};
use crate::transition_search::shift_frame_limit;

impl Project {
    /// `add_transition` with `ripple` — the overlap made by SHIFTING the
    /// incoming clip left over the end of the outgoing one, for the cut
    /// where neither clip has a frame of unused material (two whole files
    /// placed back to back, which the handle form can never join).
    ///
    /// No handle is read and `align` means nothing: the outgoing clip keeps
    /// every frame and its place, the incoming clip keeps its source window
    /// and its actions (they are clip time, and the clip moves whole), and
    /// its first frames blend over the outgoing clip's last ones. What moves
    /// is `close_gap`'s set — every clip at or after the cut on every
    /// UNLOCKED track, through the same [`shift_clips`] — so the tracks stay
    /// in sync and the timeline gets shorter by the overlap. Markers do not
    /// move, as they do not for `ripple_delete` or `close_gap`.
    ///
    /// The duration is counted in whole frames of the canvas's own grid
    /// (`time::frames_in`), capped at the frames that fit in half the
    /// shorter of the two clips back from the cut (the pair's own overlap
    /// rule, closed form), and then searched for the greatest count at which
    /// every track something moved on passes the overlap rule — clamped
    /// rather than refused, the handle form's posture. The incoming clip
    /// lands that many GRID frames back from the cut (`time::frames_back`),
    /// and everything else moves by the same delta (spec §11 #42). A clip on
    /// another track that the shift pushes into its predecessor gains a
    /// minted `cross_dissolve`, which is `close_gap`'s rule for the same
    /// shift.
    ///
    /// Five refusals, each in its own sentence: an incoming clip on a
    /// LOCKED track cannot move ([`locked_track`]); a request under one grid
    /// frame is too short ([`transition_too_short`]); a pair whose shorter
    /// clip is under two frames has no half to give; a shift every length
    /// of which would break the overlap rule somewhere it moved something;
    /// and a linked sound the shift would take below 0 (`shift_clips`,
    /// spec §11 AU-91).
    pub(crate) fn add_transition_by_shift(
        &self,
        earlier: &Clip,
        later: &Clip,
        kind: Option<TransitionKind>,
        duration: Ticks,
    ) -> Result<Outcome, String> {
        let unlocked = unlocked_tracks(self);
        if !unlocked.contains(&later.track) {
            return Ok(Outcome::Refused(locked_track(
                later.track,
                &format!(
                    "clip {} cannot be shifted left to make the overlap",
                    later.id
                ),
            )));
        }
        let fps = self.canvas.fps;
        let asked = frames_in(duration, fps);
        if asked < 1 {
            let one = snap_up_to_frame(1, fps);
            return Ok(Outcome::Refused(transition_too_short(
                later.id, duration, one,
            )));
        }
        let cut = later.start;
        // `shift_clips`'s own set, linked partners included (spec §11 AU-91).
        let mut touched: Vec<u32> = Vec::new();
        for clip in shifted(self, cut).iter().filter_map(|id| self.clip(*id)) {
            if !touched.contains(&clip.track) {
                touched.push(clip.track);
            }
        }

        let shorter = earlier.duration.min(later.duration);
        // The pair rule is in ticks; how many grid frames back from the cut
        // fit inside it is the count the shift may spend.
        let allowed = frames_within(cut, shorter / 2, fps);
        let frames = asked.min(allowed);
        if frames <= 0 {
            return Ok(Outcome::Refused(format!(
                "clips {} and {} have no room to overlap by shifting: the overlap asked \
                 for is {asked} frames and half of the shorter clip is {allowed} frames",
                earlier.id, later.id
            )));
        }
        let most = frames;
        for track in &touched {
            if let Err(why) = self.check_overlap_rule(&[], *track, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }
        if let Some(frames) = shift_frame_limit(self, cut, most, &touched) {
            let mut next = self.clone();
            let delta = frames_back(cut, frames, fps).saturating_sub(cut);
            if let Some(why) = shift_clips(&mut next, cut, delta) {
                return Ok(Outcome::Refused(why));
            }
            for track in &touched {
                if let Err(why) = next.check_overlap_rule(&[], *track, &[]) {
                    return Ok(Outcome::Refused(why));
                }
            }
            if let Some(slot) = next.clip_mut(later.id) {
                slot.transition_in = Some(match (kind, later.transition_in) {
                    (Some(kind), Some(stored)) => Transition { kind, ..stored },
                    (Some(kind), None) => Transition::minted(kind),
                    (None, Some(stored)) => stored,
                    (None, None) => Transition::minted(TransitionKind::default()),
                });
            }
            return self.finish_placement(next, &touched);
        }
        Ok(Outcome::Refused(format!(
            "clips {} and {} cannot overlap by shifting: no overlap from {most} frames down \
             to one leaves every track the shift moves inside the overlap rule",
            earlier.id, later.id
        )))
    }
}
//! `set_transition_style` — a transition's curve and whether it crossfades
//! the sound, leaving its kind alone (spec §6, table "Transitions").
//!
//! Cut out of `edit_transition.rs` under the size rule, a pure move (road
//! map "audio" AP11's toll): the op only restyles a stored transition and
//! moves no clip, so it needs none of that module's placement arithmetic.

use crate::edit_adjustment::adjustment_transition;
use crate::model::{Curve, FadeShape, Project, Transition, TransitionKind};
use crate::outcome::Outcome;

impl Project {
    /// Sets the transition's CURVE and whether it crossfades the sound
    /// (spec §6, format version 7), and the crossfade's shape (format 29,
    /// spec §11 AU-115), leaving its kind alone.
    ///
    /// A second op rather than two more arguments on
    /// [`Project::set_transition`], and the reason is the envelope: that op
    /// reads an absent `kind` and an explicit `null` as the same thing — a
    /// CLEAR — so it has no way to spell "leave the curve where it is".
    /// Here no argument is nullable, so an absent key is unambiguous and
    /// means keep.
    ///
    /// It stores on the same terms `set_transition` does: any clip, with or
    /// without an overlap, since a stored transition on a clip with no
    /// overlap is simply undrawn until one exists. With NO stored
    /// transition and at least one key given it mints
    /// (`cross_dissolve`, spec §11 R5-2) and applies the style over it;
    /// with NO key given it is an identity whatever the clip holds
    /// and never mints — asking for no change is not a way to make a
    /// transition. `Err` for an unknown clip.
    pub fn set_transition_style(
        &self,
        clip: u32,
        curve: Option<Curve>,
        audio: Option<bool>,
        audio_shape: Option<FadeShape>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?;
        let stored = target.transition_in;
        if curve.is_none() && audio.is_none() && audio_shape.is_none() {
            return Ok(Outcome::Identity);
        }
        if let Some(why) = adjustment_transition(target) {
            return Ok(Outcome::Refused(why));
        }
        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(clip) {
            let mut transition =
                stored.unwrap_or_else(|| Transition::minted(TransitionKind::default()));
            if let Some(curve) = curve {
                transition.curve = curve;
            }
            if let Some(audio) = audio {
                transition.audio = audio;
            }
            if let Some(shape) = audio_shape {
                transition.audio_shape = shape;
            }
            slot.transition_in = Some(transition);
        }
        self.finish(next)
    }
}
//! Overlaps between neighbouring clips, and THE overlap rule (spec §11).
//!
//! There is no separate transition object on the timeline: an overlap
//! between two clips on the same track *is* the transition, its length is
//! the transition's duration, and the later clip's `transition_in` says
//! which one it is (spec §5.2). So this module owns three related things —
//! finding overlaps, reporting a transition's progress at a time, and the
//! rule that says which overlaps are allowed at all:
//!
//! > A clip may overlap at most ONE neighbour on each side, and each
//! > overlap must be at most HALF of the shorter of the two clips.
//!
//! The rule is written here once and called from `edit_clip` (move, trim),
//! `edit_transition` (set_transition_duration) and `edit_time` (insert time,
//! ripple): a second
//! copy would drift, and the difference between the copies would be the
//! difference between a drop the UI animates back and a project the
//! compositor cannot tile into instructions.
//!
//! Clips never push each other (spec §11): a placement that breaks the rule
//! is refused, never repaired.
//!
//! Two clips overlapping inside a NEST are a transition on exactly the same
//! terms — the group was made out of clips that already had one — so the
//! three read-only halves of this module ([`overlap_before_of`],
//! [`overlap_after_of`], [`transition_among`]) take the container's clips as
//! a slice rather than reading `Project::clips`, and the `Project` methods
//! are the timeline's spelling of them. The rule itself stays a `Project`
//! method: nothing edits inside a nest except `nest` and `unnest`, and both
//! check the TIMELINE they are moving clips on to.

use crate::actions;
use crate::audio::Side;
use crate::edit_adjustment::adjustment_overlap;
use crate::model::{Clip, Project, Transition, TransitionKind};
use crate::model_query::clips_on;
use crate::time::Ticks;

/// One overlap: `earlier` starts first, `later` is the clip whose
/// `transition_in` names the kind, and `start`/`duration` are the span in
/// PROJECT time that both clips cover.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Overlap {
    pub earlier: u32,
    pub later: u32,
    pub start: Ticks,
    pub duration: Ticks,
}

/// The maximum overlap permitted for this pair by the half-shorter rule.
pub(crate) fn overlap_limit(a: &Clip, b: &Clip) -> Ticks {
    a.duration.min(b.duration) / 2
}

/// The overlap between two clips, `earlier` being the one that starts
/// first. `None` when they merely touch: a zero-length overlap is not a
/// transition, it is a cut, and treating it as one would put a degenerate
/// division into every progress computation downstream.
fn overlap_of(earlier: &Clip, later: &Clip) -> Option<Overlap> {
    let start = earlier.start.max(later.start);
    let end = earlier
        .start
        .saturating_add(earlier.duration)
        .min(later.start.saturating_add(later.duration));
    let duration = end.saturating_sub(start);
    if duration <= 0 {
        return None;
    }
    Some(Overlap {
        earlier: earlier.id,
        later: later.id,
        start,
        duration,
    })
}

/// Where `t` sits inside the overlap, 0 at its first tick and approaching 1
/// at its last. Half-open at the end, so the tick the earlier clip ends on
/// is already past the transition and the instruction tiling has no
/// ambiguity. `None` when `t` is outside.
fn progress_in(overlap: &Overlap, t: Ticks) -> Option<f64> {
    let end = overlap.start.saturating_add(overlap.duration);
    if t < overlap.start || t >= end || overlap.duration <= 0 {
        return None;
    }
    let elapsed = t.saturating_sub(overlap.start) as f64;
    Some((elapsed / overlap.duration as f64).clamp(0.0, 1.0))
}

/// The whole transition the LATER clip of a pair carries. An overlap is
/// always a transition, so a clip that overlaps its predecessor with no
/// `transition_in` — only possible in hand-written JSON; `move_clip` sets
/// one when a clip gains an overlap — renders as the default cross
/// dissolve rather than as a hard cut through two visible layers.
///
/// The fallback is `Transition::default()` and deliberately NOT
/// `Transition::minted`: this is what a FILE means by an absent key, and a
/// version-6 project's bare overlap must go on drawing linearly and
/// silently (spec §11, R5-2). Minting is what an EDIT does.
fn transition_of_later(later: &Clip) -> Transition {
    later.transition_in.unwrap_or_default()
}

/// The overlap between `clip` and its predecessor among `clips` — one
/// container's clips, the timeline's or a nest's. `None` for an unknown
/// clip, the first clip on its track, or a plain cut.
pub(crate) fn overlap_before_of(clips: &[Clip], clip: u32) -> Option<Overlap> {
    let target = clips.iter().find(|c| c.id == clip)?;
    let ordered = clips_on(clips, target.track);
    let index = ordered.iter().position(|c| c.id == clip)?;
    let previous = ordered.get(index.checked_sub(1)?)?;
    overlap_of(previous, target)
}

/// The overlap between `clip` and its successor among `clips` — the one the
/// SUCCESSOR's `transition_in` describes.
pub(crate) fn overlap_after_of(clips: &[Clip], clip: u32) -> Option<Overlap> {
    let target = clips.iter().find(|c| c.id == clip)?;
    let ordered = clips_on(clips, target.track);
    let index = ordered.iter().position(|c| c.id == clip)?;
    let next = ordered.get(index.checked_add(1)?)?;
    overlap_of(target, next)
}

/// The transition `clip` is playing at `t`, among the clips of its own
/// container — [`Project::transition_at`]'s implementation, and the one a
/// nested clip is evaluated with (at NEST time, not project time).
///
/// The progress is EASED by the transition's own `curve` (format version 7)
/// before it is returned, so every consumer of it gets one number and none
/// of them has to know the curve exists. `actions::ease` is the crate's one
/// implementation of the four curves, and `Curve::Linear` is the identity —
/// which is what makes a version-6 file's transitions byte-identical to
/// what they were.
pub(crate) fn transition_among(
    clips: &[Clip],
    clip: u32,
    t: Ticks,
) -> Option<(TransitionKind, f64, bool, u32)> {
    let target = clips.iter().find(|c| c.id == clip)?;
    if let Some(overlap) = overlap_before_of(clips, clip) {
        if let Some(progress) = progress_in(&overlap, t) {
            // This clip is the later one, so it carries the transition.
            let transition = transition_of_later(target);
            let eased = actions::ease(transition.curve, progress);
            return Some((transition.kind, eased, true, overlap.earlier));
        }
    }
    if let Some(overlap) = overlap_after_of(clips, clip) {
        if let Some(progress) = progress_in(&overlap, t) {
            let later = clips.iter().find(|c| c.id == overlap.later)?;
            let transition = transition_of_later(later);
            let eased = actions::ease(transition.curve, progress);
            return Some((transition.kind, eased, false, overlap.later));
        }
    }
    None
}

/// The crossfade `clip` is in at `t`, among the clips of its own container:
/// `(the later clip's transition, eased progress, is_incoming)`.
///
/// The audio twin of [`transition_among`], and it differs from it in one
/// way that matters: on [`Side::Left`] the overlap is CLOSED at its end, so
/// the outgoing clip's last sample reads p = 1 and its fade finishes at
/// zero. `progress_in` is half-open — right for the picture, where the tick
/// the earlier clip ends on is already past the transition and the
/// instruction tiling must have no ambiguity — but an envelope evaluated
/// from the LEFT at that tick is asking for the limit approaching it, and
/// a `None` there would read as gain 1 and undo the whole fade on the last
/// breakpoint.
///
/// The partner id is not returned because nothing in the envelope needs it:
/// each stage multiplies its OWN term, and the two clips of a pair are
/// different voices on different composition tracks.
pub(crate) fn crossfade_among(
    clips: &[Clip],
    clip: u32,
    t: Ticks,
    side: Side,
) -> Option<(Transition, f64, bool)> {
    let closed = |overlap: &Overlap| -> Option<f64> {
        if let Some(progress) = progress_in(overlap, t) {
            return Some(progress);
        }
        if side == Side::Left && overlap.duration > 0 {
            let end = overlap.start.saturating_add(overlap.duration);
            if t == end {
                return Some(1.0);
            }
        }
        None
    };

    let target = clips.iter().find(|c| c.id == clip)?;
    if let Some(overlap) = overlap_before_of(clips, clip) {
        if let Some(progress) = closed(&overlap) {
            let transition = transition_of_later(target);
            return Some((transition, actions::ease(transition.curve, progress), true));
        }
    }
    if let Some(overlap) = overlap_after_of(clips, clip) {
        if let Some(progress) = closed(&overlap) {
            let later = clips.iter().find(|c| c.id == overlap.later)?;
            let transition = transition_of_later(later);
            return Some((transition, actions::ease(transition.curve, progress), false));
        }
    }
    None
}

impl Project {
    /// Every overlap on `track`, in time order.
    ///
    /// Only ADJACENT clips (in start order) are considered, which is the
    /// timeline's model of a transition: it sits between two neighbours.
    /// The overlap rule guarantees nothing else can overlap anyway, and
    /// [`Project::check_overlap_rule`] is what detects a project where
    /// something does.
    pub fn overlaps_on_track(&self, track: u32) -> Vec<Overlap> {
        let clips = self.clips_on_track(track);
        let mut out = Vec::new();
        for pair in clips.windows(2) {
            if let (Some(earlier), Some(later)) = (pair.first(), pair.get(1)) {
                if let Some(overlap) = overlap_of(earlier, later) {
                    out.push(overlap);
                }
            }
        }
        out
    }

    /// The overlap between `clip` and its predecessor on the same track —
    /// the one its own `transition_in` describes. `None` for an unknown
    /// clip, the first clip on a track, or a plain cut.
    pub fn overlap_before(&self, clip: u32) -> Option<Overlap> {
        overlap_before_of(&self.clips, clip)
    }

    /// The overlap between `clip` and its successor on the same track — the
    /// one the SUCCESSOR's `transition_in` describes. `None` for an unknown
    /// clip, the last clip on a track, or a plain cut.
    pub fn overlap_after(&self, clip: u32) -> Option<Overlap> {
        overlap_after_of(&self.clips, clip)
    }

    /// The transition `clip` is playing at project time `t`, as
    /// `(kind, progress, is_incoming, partner)`.
    ///
    /// Both clips of a pair report the SAME kind and the SAME progress —
    /// the compositor draws them as one pair (spec §7.3) — and
    /// `is_incoming` is the `role` field: true for the later clip coming
    /// in, false for the earlier one going out. `partner` is the other
    /// clip's id.
    ///
    /// `None` when `t` is a plain cut or ordinary body of the clip.
    pub fn transition_at(&self, clip: u32, t: Ticks) -> Option<(TransitionKind, f64, bool, u32)> {
        transition_among(&self.clips, clip, t)
    }

    /// Checks the overlap rule against the state `track` would be left in.
    ///
    /// `candidates` are the clips in their PROPOSED positions (a move's
    /// destinations, a trim's result, a new clip); `ignore` lists clip ids
    /// to treat as absent, which is how a move removes the clips from where
    /// they were. A candidate's own id is ignored too, so a caller that
    /// forgets `ignore` still gets the right answer instead of a clip
    /// colliding with itself. Candidates for other tracks are skipped, so a
    /// multi-track move can pass the whole set to each destination track.
    ///
    /// The check is over the WHOLE resulting track, not just around the
    /// candidates: the rule is an invariant of the track, and the plan's
    /// A/B assignment (spec §7.2, at most two composition tracks per
    /// timeline track) depends on it holding everywhere.
    ///
    /// `Ok(())` or an `Err` naming the first violation, which the calling
    /// op hands straight on as its refusal — `Outcome::Refused` carrying
    /// THIS sentence, `reason_out` at the FFI, an animate-back in the UI.
    /// The rule is therefore written once: the clip ids and the tick counts
    /// a caller acts on are the ones computed here.
    pub fn check_overlap_rule(
        &self,
        candidates: &[Clip],
        track: u32,
        ignore: &[u32],
    ) -> Result<(), String> {
        let mut placed: Vec<&Clip> = self
            .clips
            .iter()
            .filter(|c| {
                c.track == track
                    && !ignore.contains(&c.id)
                    && !candidates.iter().any(|k| k.id == c.id)
            })
            .collect();
        placed.extend(candidates.iter().filter(|c| c.track == track));
        placed.sort_by_key(|c| (c.start, c.id));

        for i in 0..placed.len() {
            if let (Some(a), Some(b)) = (placed.get(i), placed.get(i + 1)) {
                if let Some(overlap) = overlap_of(a, b) {
                    // No overlap may hold an adjustment clip (spec §11
                    // GR-6): it cannot take the transition an overlap is.
                    if let Some(why) = adjustment_overlap(a, b) {
                        return Err(why);
                    }
                    // Half of the SHORTER clip. Integer halving truncates,
                    // which errs toward refusing — the safe side, since an
                    // over-long overlap is what breaks the A/B assignment.
                    let limit = overlap_limit(a, b);
                    if overlap.duration > limit {
                        return Err(format!(
                            "clips {} and {} would overlap by {} ticks, more than half of the \
                             shorter clip ({} ticks)",
                            a.id, b.id, overlap.duration, limit
                        ));
                    }
                }
            }
            // Clips are in start order, so a clip that reaches any
            // non-adjacent clip necessarily reaches the one two along:
            // testing i and i+2 catches every "two neighbours on one side"
            // case in a single linear pass.
            if let (Some(a), Some(b), Some(c)) =
                (placed.get(i), placed.get(i + 1), placed.get(i + 2))
            {
                if overlap_of(a, c).is_some() {
                    return Err(format!(
                        "clip {} would overlap more than one neighbour on one side \
                         (clips {} and {})",
                        a.id, b.id, c.id
                    ));
                }
            }
        }
        Ok(())
    }
}
//! Bounded searches for the two ways a hard cut gains an overlap.
//!
//! The handle path is monotone after an affected track passes the original
//! overlap rule: the outer neighbours are bounded away before searching,
//! and growing either clip cannot invalidate an already valid outer pair.
//! At the cut itself, with extensions `tail` and `head`, the two limits are
//! `tail + 2*head <= A.duration` and `2*tail + head <= B.duration`.
//! Reducing either side improves both; inward grid snapping only reduces
//! an extension. A pair that swaps order or contains its partner cannot
//! pass before these constraints do. Thus the old decrement path has one
//! pass/fail boundary and can be searched without enumerating frames.
//!
//! Ripple has no such global monotonicity: a moved clip can pass across a
//! fixed clip and become valid again. Its forbidden integer intervals are
//! calculated exactly instead, in whole frames of the canvas's own grid
//! counted back from the cut (`time::frames_within`, spec §11 #42), so a
//! shift of `k` frames is `time::frames_back(cut, k) − cut` and not
//! `k` times `Project::frame` (the first frame's length, which is not
//! every frame's at such a rate, spec §11 #174). Pairwise half-shorter
//! checks also enforce the non-adjacent rule for positive durations: if A
//! reaches C across B,
//! either B ends before C (then A covers all B), or A/B staying within
//! half B puts A's end before B's midpoint while B/C staying within half B
//! puts C's start after that midpoint, contradicting A reaching C.

use crate::edit_time::shifted;
use crate::model::Project;
use crate::time::{frames_within, Ticks};
use crate::transition::overlap_limit;

/// The old larger-side decrement path, including its head-first tie rule.
pub(crate) fn reduced_split(tail: Ticks, head: Ticks, total: Ticks) -> (Ticks, Ticks) {
    let smaller = tail.min(head);
    if total > 2 * smaller {
        if tail > head {
            (total - head, head)
        } else {
            (tail, total - tail)
        }
    } else {
        ((total + 1) / 2, total / 2)
    }
}

/// Greatest passing integer in `0..=limit`; zero must pass and the
/// predicate must be downward closed. At most 64 probes for i64 limits.
pub(crate) fn largest_passing(limit: Ticks, mut fits: impl FnMut(Ticks) -> bool) -> Ticks {
    let mut good = 0_i128;
    let mut bad = i128::from(limit) + 1;
    while good + 1 < bad {
        let mid = good + (bad - good) / 2;
        if fits(mid as Ticks) {
            good = mid;
        } else {
            bad = mid;
        }
    }
    good as Ticks
}

/// Greatest positive shift count not forbidden by a fixed/moved pair on
/// any touched track. The caller checked the original affected tracks and
/// supplies the same touched tracks as `shift_clips`; the moved partition
/// is `shift_clips`'s own set ([`shifted`], linked partners included).
pub(crate) fn shift_frame_limit(
    project: &Project,
    cut: Ticks,
    limit: Ticks,
    touched: &[u32],
) -> Option<Ticks> {
    let mut forbidden: Vec<(i128, i128)> = Vec::new();
    let fps = project.canvas.fps;
    // A threshold outside the tick range saturates: past either end, no
    // count the search can reach is on the other side of it.
    let within = |span: i128| {
        let span = Ticks::try_from(span).unwrap_or(if span < 0 { Ticks::MIN } else { Ticks::MAX });
        i128::from(frames_within(cut, span, fps))
    };
    let maximum = i128::from(limit);
    let moving = shifted(project, cut);
    for track in touched {
        let (moved, fixed): (Vec<_>, Vec<_>) = project
            .clips
            .iter()
            .filter(|c| c.track == *track)
            .partition(|c| moving.contains(&c.id));
        for a in &fixed {
            for b in &moved {
                let s = i128::from(a.start);
                let e = s + i128::from(a.duration);
                let m = i128::from(b.start);
                let n = m + i128::from(b.duration);
                let half = i128::from(overlap_limit(a, b));
                // Too much overlap iff m-e+L < shift(k) < n-s-L, where
                // shift(k) = cut - frames_back(cut, k) grows with k; the
                // strict upper bound uses one less tick.
                let low = within(m - e + half) + 1;
                let high = within(n - s - half - 1);
                let low = low.max(1);
                let high = high.min(maximum);
                if low <= high {
                    forbidden.push((low, high));
                }
            }
        }
    }
    forbidden.sort_unstable_by_key(|interval| interval.0);
    let mut best = maximum;
    // Scanning from the highest interval down finds the greatest uncovered
    // count even if the forbidden set has holes after pair crossings.
    for &(low, high) in forbidden.iter().rev() {
        if low <= best && best <= high {
            best = low - 1;
        }
    }
    (best > 0).then_some(best as Ticks)
}

        let neighbours = snapshot.clips.filter { $0.track == clip.track && $0.id != clip.id }
        if neighbours.contains(where: { $0.start < clip.start && $0.end > clip.start }) {
            return .overlap
        }
        if neighbours.contains(where: { $0.end == clip.start }) {
            return .hardCut
        }
        return .neither
    }
}
